"use client";

import { useCallback, useEffect, useId, useRef, useState, type KeyboardEvent, type MouseEvent } from 'react';
import './expanding-menu.css';

export type ExpandingMenuItem = {
  id: string;
  label: string;
  href: string;
  description?: string;
};

export type ExpandingMenuProps = {
  items: ExpandingMenuItem[];
  activeId?: string;
  className?: string;
  label?: string;
  onNavigate?: (id: string, event: MouseEvent<HTMLAnchorElement>) => void;
  onOpenChange?: (open: boolean) => void;
};

/** An inline navigation disclosure. It leaves the rest of the page available. */
export function ExpandingMenu({ items, activeId, className = '', label = 'Menu', onNavigate, onOpenChange }: ExpandingMenuProps) {
  const [open, setOpen] = useState(false);
  const openRef = useRef(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const links = useRef<Array<HTMLAnchorElement | null>>([]);
  const focusOnOpen = useRef<'first' | 'last' | null>(null);
  const panelId = useId();

  const changeOpen = useCallback((next: boolean, restoreFocus = false) => {
    if (restoreFocus) trigger.current?.focus();
    if (openRef.current === next) return;
    openRef.current = next;
    setOpen(next);
    onOpenChange?.(next);
  }, [onOpenChange]);

  useEffect(() => {
    if (!open) return;
    if (focusOnOpen.current) {
      links.current[focusOnOpen.current === 'first' ? 0 : items.length - 1]?.focus();
      focusOnOpen.current = null;
    }
    const dismiss = (event: PointerEvent) => {
      if (event.target instanceof Node && !root.current?.contains(event.target)) changeOpen(false);
    };
    document.addEventListener('pointerdown', dismiss);
    return () => document.removeEventListener('pointerdown', dismiss);
  }, [open, items.length, changeOpen]);

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape' && openRef.current) {
      event.preventDefault();
      event.stopPropagation();
      changeOpen(false, true);
      return;
    }
    if (event.target === trigger.current && (event.key === 'ArrowDown' || event.key === 'ArrowUp')) {
      event.preventDefault();
      const edge = event.key === 'ArrowDown' ? 'first' : 'last';
      if (openRef.current) links.current[edge === 'first' ? 0 : items.length - 1]?.focus();
      else {
        focusOnOpen.current = edge;
        changeOpen(true);
      }
    }
  }

  return <div
    ref={root}
    className={`ac-expand-menu ${className}`.trim()}
    data-open={open}
    onKeyDown={handleKeyDown}
    onBlur={(event) => {
      if (event.relatedTarget instanceof Node && !event.currentTarget.contains(event.relatedTarget)) changeOpen(false);
    }}
  >
    <button
      ref={trigger}
      type="button"
      className="ac-expand-trigger"
      aria-expanded={open}
      aria-controls={panelId}
      onClick={() => changeOpen(!openRef.current)}
    >
      <span className="ac-expand-mark" aria-hidden="true">✳</span>
      <span className="ac-expand-label">{label}</span>
      <span className="ac-expand-toggle" aria-hidden="true"><span /><span /></span>
    </button>
    <div id={panelId} hidden={!open} className="ac-expand-panel">
      {open && <>
        <div className="ac-expand-heading"><span>Find your way</span><span>{String(items.length).padStart(2, '0')} destinations</span></div>
        <nav aria-label={label} className="ac-expand-links">
          {items.map((item, index) => <a
            key={item.id}
            ref={(element) => { links.current[index] = element; }}
            href={item.href}
            className="ac-expand-link"
            aria-current={activeId === item.id ? 'page' : undefined}
            onClick={(event) => {
              onNavigate?.(item.id, event);
              changeOpen(false, true);
            }}
          >
            <span className="ac-expand-number" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>
            <span className="ac-expand-copy"><span className="ac-expand-title">{item.label}</span>{item.description && <span className="ac-expand-description">{item.description}</span>}</span>
            <svg className="ac-expand-arrow" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14" /></svg>
          </a>)}
        </nav>
      </>}
    </div>
  </div>;
}

.ac-expand-menu {
  --ac-expand-paper: var(--ac-surface, var(--ac-expanding-menu-theme-paper, #f8f7f0));
  --ac-expand-ink: var(--ac-ink, var(--ac-expanding-menu-theme-ink, #25271f));
  --ac-expand-accent: var(--ac-accent, #df5c38);
  position: relative;
  width: 350px;
  max-width: 100%;
  color: var(--ac-expand-ink);
  font-family: var(--ac-font, inherit);
  isolation: isolate;
}
.ac-expand-menu *, .ac-expand-menu *::before, .ac-expand-menu *::after { box-sizing: border-box; }
.ac-expand-trigger {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 54px;
  border: 1px solid color-mix(in srgb, var(--ac-expand-ink) 14%, transparent);
  border-radius: 32px;
  padding: 7px 17px 7px 8px;
  background: var(--ac-expand-paper);
  color: inherit;
  cursor: pointer;
  font: inherit;
  box-shadow: 0 3px 0 color-mix(in srgb, var(--ac-expand-ink) 8%, transparent);
  -webkit-tap-highlight-color: transparent;
}
.ac-expand-mark { display: grid; place-items: center; width: 38px; height: 38px; flex: 0 0 38px; border-radius: 50%; color: var(--ac-expand-paper); background: var(--ac-expand-ink); font-size: 26px; line-height: 1; transition: transform 450ms cubic-bezier(.2,.8,.2,1); }
.ac-expand-label { flex: 1; text-align: left; font-size: 14px; font-weight: 600; letter-spacing: -.025em; }
.ac-expand-toggle { position: relative; width: 20px; height: 20px; }
.ac-expand-toggle span { position: absolute; left: 2px; top: 9px; width: 16px; height: 1.5px; border-radius: 1px; background: currentColor; transition: transform 250ms, opacity 250ms; }
.ac-expand-toggle span:last-child { transform: rotate(90deg); }
.ac-expand-menu[data-open="true"] .ac-expand-mark { transform: rotate(90deg); }
.ac-expand-menu[data-open="true"] .ac-expand-toggle span:last-child { transform: rotate(0); opacity: 0; }
.ac-expand-panel { margin-top: 9px; padding: 18px 15px 9px; border: 1px solid color-mix(in srgb, var(--ac-expand-ink) 14%, transparent); border-radius: 22px; background: var(--ac-expand-paper); box-shadow: 0 16px 35px color-mix(in srgb, var(--ac-expand-ink) 8%, transparent); transform-origin: top center; animation: ac-expand-enter 280ms cubic-bezier(.2,.8,.2,1) both; }
.ac-expand-panel[hidden] { display: none; }
.ac-expand-heading { display: flex; justify-content: space-between; gap: 12px; padding: 0 2px 13px; color: color-mix(in srgb, var(--ac-expand-ink) 50%, transparent); font-size: 9px; font-weight: 500; text-transform: uppercase; letter-spacing: .09em; }
.ac-expand-links { display: flex; flex-direction: column; }
.ac-expand-link { position: relative; display: flex; align-items: center; gap: 12px; min-height: 66px; padding: 12px 4px; border-top: 1px solid color-mix(in srgb, var(--ac-expand-ink) 12%, transparent); color: inherit; text-decoration: none; transition: color 180ms, padding 180ms; }
.ac-expand-number { align-self: flex-start; padding-top: 5px; color: color-mix(in srgb, var(--ac-expand-ink) 45%, transparent); font-size: 10px; font-variant-numeric: tabular-nums; }
.ac-expand-copy { display: flex; flex: 1; min-width: 0; flex-direction: column; gap: 4px; }
.ac-expand-title { font-family: var(--ac-serif, Georgia, serif); font-size: 26px; font-weight: 400; line-height: 1.1; letter-spacing: -.04em; overflow-wrap: anywhere; }
.ac-expand-description { color: color-mix(in srgb, var(--ac-expand-ink) 58%, transparent); font-size: 10px; line-height: 1.45; }
.ac-expand-arrow { flex: 0 0 20px; transition: transform 200ms; }
.ac-expand-link[aria-current="page"] { color: var(--ac-expand-accent); }
.ac-expand-link[aria-current="page"] .ac-expand-number { color: inherit; }
.ac-expand-trigger:focus-visible, .ac-expand-link:focus-visible { outline: 2px solid var(--ac-expand-accent); outline-offset: 4px; }
@media (hover: hover) { .ac-expand-link:hover { color: var(--ac-expand-accent); padding-left: 10px; } .ac-expand-link:hover .ac-expand-arrow { transform: translate(2px,-2px); } }
@keyframes ac-expand-enter { from { opacity: 0; transform: translateY(-7px) scale(.97); } to { opacity: 1; transform: translateY(0) scale(1); } }
@media (prefers-reduced-motion: reduce) { .ac-expand-menu *, .ac-expand-menu *::before, .ac-expand-menu *::after { animation: none !important; transition: none !important; } }

/* Neutral defaults follow the page theme; explicit component colors keep priority. */
:where([data-theme="light"], .light) .ac-expand-menu {
  --ac-expanding-menu-theme-paper: #fbfcf8;
  --ac-expanding-menu-theme-ink: #25271f;
}
:where([data-theme="dark"], .dark) .ac-expand-menu {
  --ac-expanding-menu-theme-paper: #242a21;
  --ac-expanding-menu-theme-ink: #e8eddf;
}
